from collections import defaultdict, Counter

def components(mat, color, r0=0, r1=None, c0=0, c1=None, conn=4):
    if r1 is None:r1=len(mat)
    if c1 is None:c1=len(mat[0])
    seen=set(); out=[]
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    if conn==8: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
    for r in range(r0,r1):
      for c in range(c0,c1):
        if mat[r][c]!=color or (r,c) in seen:continue
        st=[(r,c)]; seen.add((r,c)); pts=[]
        while st:
          x,y=st.pop();pts.append((x,y))
          for dx,dy in dirs:
            p=(x+dx,y+dy)
            if r0<=p[0]<r1 and c0<=p[1]<c1 and p not in seen and mat[p[0]][p[1]]==color:
              seen.add(p);st.append(p)
        out.append(pts)
    return out

def norm(pts):
    mr=min(x for x,y in pts); mc=min(y for x,y in pts)
    return tuple(sorted((x-mr,y-mc) for x,y in pts))

def transforms(shape, rot=True, refl=True):
    pts=shape
    outs=[]
    for reflv in ([False,True] if refl else [False]):
      for k in range(4 if rot else 1):
        q=[(x, -y if reflv else y) for x,y in pts]
        for _ in range(k): q=[(y,-x) for x,y in q]
        mi=min(x for x,y in q); mj=min(y for x,y in q)
        outs.append(tuple(sorted((x-mi,y-mj) for x,y in q)))
    return outs

