def canon(shape, allow_reflect=False):
    forms=[]
    for reflv in ([False,True] if allow_reflect else [False]):
      q=[(x, -y if reflv else y) for x,y in shape]
      for k in range(4):
        t=q
        for _ in range(k): t=[(y,-x) for x,y in t]
        mi=min(x for x,y in t); mj=min(y for x,y in t)
        forms.append(tuple(sorted((x-mi,y-mj) for x,y in t)))
    return min(forms)

